 { json: { requestId: 'QF-2002', firstName: 'David', email: 'david@example.com', whatsappNumber: '+15550102032', pipelineStage: 'Won', nextActionAt: new Date(now.getTime() - 3600000).toISOString(), followUpCount: 1, stopFollowUps: false, lastInboundAt: null } },
 { json: { requestId: 'QF-2003', firstName: 'Lina', email: 'lina@example.com', whatsappNumber: '+15550102033', pipelineStage: 'Following Up', nextActionAt: new Date(now.getTime() + 86400000).toISOString(), followUpCount: 2, stopFollowUps: false, lastInboundAt: null } },
 { json: { requestId: 'QF-2004', firstName: 'Noah', email: 'noah@example.com', whatsappNumber: '+15550102034', pipelineStage: 'Paused', nextActionAt: new Date(now.getTime() - 3600000).toISOString(), followUpCount: 2, stopFollowUps: true, lastInboundAt: null } }
];

const terminalStages = new Set(['Won', 'Lost', 'Paused', 'Inspection Scheduled']);
const maximumFollowUps = 4;
const now = Date.now();
return $input.all().map((item) => {
 const lead = item.json;
 const reasons = [];
 if (lead.stopFollowUps) reasons.push('stop flag enabled');
 if (terminalStages.has(lead.pipelineStage)) reasons.push(`terminal stage: ${lead.pipelineStage}`);
 if (Number(lead.followUpCount || 0) >= maximumFollowUps) reasons.push('maximum follow-ups reached');
 if (lead.lastInboundAt) reasons.push('customer has replied');
 if (new Date(lead.nextActionAt).getTime() > now) reasons.push('next action is not due');
 const eligible = reasons.length === 0;
 return { json: { ...lead, followUpDecision: { eligible, reasons, evaluatedAt: new Date().toISOString() } } };
});

const cadenceDays = [1, 3, 7, 14];
return $input.all().map((item) => {
 const lead = item.json;
 if (!lead.followUpDecision.eligible) return { json: { ...lead, action: 'SKIP', outboundPreview: null } };
 const number = Number(lead.followUpCount || 0) + 1;
 const nextDelay = cadenceDays[number] ?? null;
 const body = `Hi ${lead.firstName}, I am following up on cleaning quote ${lead.requestId}. Would you like to proceed, ask a question, or pause the request?`;
 return { json: { ...lead, action: 'SEND_BOTH_CHANNELS', followUpCount: number, nextActionAt: nextDelay ? new Date(Date.now() + nextDelay * 86400000).toISOString() : null, outboundPreview: { email: { to: lead.email, subject: `Following up on ${lead.requestId}`, body }, whatsapp: { to: lead.whatsappNumber, templateKey: 'quote_follow_up', body } } } };
});
